<?php
/** @noinspection PhpUnusedParameterInspection */
declare(strict_types=1);

// Test generated by Claude Code.

namespace Tests\Offer\Access\Controller;

use Module\Offer\Action\Command\ChangeVisibilityCmd;
use Module\Offer\Action\Query\AdminGetListFiltersQry;
use Module\Offer\Action\Query\AdminGetOfferDetailsQry;
use Module\Offer\Action\Query\AdminGetOfferListQry;
use Module\User\Action\Command\AdminLoginCmd;
use Module\User\Action\Dto\AdminLoginRequestDto;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Symfony\Component\HttpKernel\Log\Logger;
use Tests\ApplicationTestCase;

class OfferAdminControllerTest extends ApplicationTestCase
{
    private string $adminToken;

    protected function setUp(): void
    {
        parent::setUp();

        $response = $this->client->getContainer()->get(AdminLoginCmd::class)->handle(
            new AdminLoginRequestDto('test-offer@example.com')
        );
        $this->adminToken = $response->token;
    }

    /**
     * @param class-string         $action
     * @param array<string, mixed> $dto
     */
    #[Test, DataProvider('dataProviderEndpoints')]
    public function blockAccessWithoutValidToken(
        string $method,
        string $path,
        string $action,
        array $dto,
        int $expected,
    ): void {
        $mock = $this->createStub($action);
        $this->client->getContainer()->set($action, $mock);
        $this->client->getContainer()->set('logger', new Logger('error', '/dev/null'));

        $this->client->jsonRequest($method, '/api' . $path, $dto);

        $this->assertResponseStatusCodeSame(401);
    }

    /**
     * @param class-string         $action
     * @param array<string, mixed> $dto
     */
    #[Test, DataProvider('dataProviderEndpoints')]
    public function blockAccessWithInvalidToken(
        string $method,
        string $path,
        string $action,
        array $dto,
        int $expected,
    ): void {
        $mock = $this->createStub($action);
        $this->client->getContainer()->set($action, $mock);
        $this->client->getContainer()->set('logger', new Logger('error', '/dev/null'));

        $this->client->jsonRequest($method, '/api' . $path, $dto, ['HTTP_AUTHORIZATION' => 'Bearer invalid_token']);

        $this->assertResponseStatusCodeSame(401);
    }

    /**
     * @param class-string         $action
     * @param array<string, mixed> $dto
     */
    #[Test, DataProvider('dataProviderEndpoints')]
    public function allowWithValidToken(
        string $method,
        string $path,
        string $action,
        array $dto,
        int $expected,
    ): void {
        $mock = $this->createStub($action);
        $this->client->getContainer()->set($action, $mock);

        $this->client->jsonRequest($method, '/api' . $path, $dto, ['HTTP_AUTHORIZATION' => 'Bearer ' . $this->adminToken]);

        $this->assertResponseStatusCodeSame($expected);
    }

    /**
     * @return array<int, array<string, mixed>>
     */
    public static function dataProviderEndpoints(): array
    {
        return [
            [
                'method' => 'get',
                'path' => '/admin/offer/filters',
                'action' => AdminGetListFiltersQry::class,
                'dto' => [],
                'expected' => 200,
            ],
            [
                'method' => 'get',
                'path' => '/admin/offer/list',
                'action' => AdminGetOfferListQry::class,
                'dto' => [],
                'expected' => 200,
            ],
            [
                'method' => 'get',
                'path' => '/admin/offer/1',
                'action' => AdminGetOfferDetailsQry::class,
                'dto' => [],
                'expected' => 200,
            ],
            [
                'method' => 'post',
                'path' => '/admin/offer/change-visibility',
                'action' => ChangeVisibilityCmd::class,
                'dto' => ['id' => 1, 'version' => 1, 'visible' => true],
                'expected' => 200,
            ],
        ];
    }
}
